import React, { useRef, useState, useCallback } from 'react';
import {
  StyleSheet,
  View,
  Text,
  TouchableOpacity,
  SafeAreaView,
  StatusBar,
  ScrollView,
} from 'react-native';
import Icon from 'react-native-vector-icons/MaterialCommunityIcons';
import {
  OtpVerification,
  OtpVerificationRef,
  OTP_CONFIG,
} from '../../components/otp';

export interface OtpVerificationExampleScreenProps {
  onBack?: () => void;
  onLoginSuccess?: () => void;
}

export const OtpVerificationExampleScreen: React.FC<OtpVerificationExampleScreenProps> = ({
  onBack,
  onLoginSuccess,
}) => {
  const otpRef = useRef<OtpVerificationRef>(null);
  const [status, setStatus] = useState<string>('Awaiting code entry');
  const [lastCode, setLastCode] = useState<string>('');
  const [isVerified, setIsVerified] = useState<boolean>(false);


  // Fake verification handler:
  // Resolves true after 800ms for '4719', false otherwise
  const fakeVerify = useCallback(async (code: string): Promise<boolean> => {
    setStatus(`Verifying ${code}...`);
    setLastCode(code);

    await new Promise((resolve) => setTimeout(resolve, 800));

    const isValid = code === '4719';
    setStatus(isValid ? 'Code 4719 verified!' : 'Invalid code! Triggering shake...');
    return isValid;
  }, []);

  const handleVerified = useCallback(() => {
    setStatus('Verified successfully! Sequence complete.');
    setIsVerified(true);
    if (onLoginSuccess) {
      setTimeout(() => {
        onLoginSuccess();
      }, 1200);
    }
  }, [onLoginSuccess]);

  const handleReset = useCallback(() => {
    setStatus('Awaiting code entry');
    setLastCode('');
    setIsVerified(false);
    otpRef.current?.reset();
  }, []);

  const handleReplay = useCallback(() => {
    setStatus('Replaying verification animation...');
    setIsVerified(false);
    otpRef.current?.replay();
  }, []);

  const handleFillSuccess = useCallback(() => {
    otpRef.current?.reset();
    setIsVerified(false);
    setTimeout(() => {
      otpRef.current?.setCode('4719');
    }, 100);
  }, []);

  const handleFillFail = useCallback(() => {
    otpRef.current?.reset();
    setIsVerified(false);
    setTimeout(() => {
      otpRef.current?.setCode('1234');
    }, 100);
  }, []);

  return (
    <SafeAreaView style={styles.safeArea}>
      <StatusBar barStyle="light-content" backgroundColor={OTP_CONFIG.COLORS.bgPage} />

      {/* Top Navigation Bar with Back Button */}
      {onBack && (
        <View style={styles.navBar}>
          <TouchableOpacity style={styles.backButton} onPress={onBack} activeOpacity={0.7}>
            <Icon name="arrow-left" size={20} color="#9ca3af" />
            <Text style={styles.backButtonText}>Back to Email Login</Text>
          </TouchableOpacity>
        </View>
      )}

      <ScrollView
        contentContainerStyle={styles.scrollContent}
        keyboardShouldPersistTaps="handled"
      >
        {/* Screen Header */}
        <View style={styles.topInfo}>
          <Text style={styles.headerBadge}>DEMO • REACT NATIVE CLI</Text>
          <Text style={styles.headerSubtitle}>
            Test OTP: <Text style={styles.codeHighlight}>4719</Text> (any other code fails)
          </Text>
        </View>

        {/* The Animated OTP Component Card */}
        <View style={styles.cardContainer}>
          <OtpVerification
            ref={otpRef}
            length={4}
            phoneNumber="+1 415 ••• 0142"
            verify={fakeVerify}
            onComplete={(code) => setLastCode(code)}
            onVerified={handleVerified}
          />
        </View>

        {/* Live Status Indicator */}
        <View style={styles.statusBox}>
          <View style={styles.statusIndicatorRow}>
            <View
              style={[
                styles.statusDot,
                status.includes('successfully')
                  ? styles.statusDotGreen
                  : status.includes('Invalid')
                  ? styles.statusDotRed
                  : styles.statusDotYellow,
              ]}
            />
            <Text style={styles.statusText}>{status}</Text>
          </View>
          {lastCode ? (
            <Text style={styles.statusDetail}>Last input: {lastCode}</Text>
          ) : null}
        </View>

        {/* Quick Test Action Buttons */}
        <View style={styles.actionsContainer}>
          <Text style={styles.actionsTitle}>TEST CONTROLS</Text>

          <View style={styles.buttonsRow}>
            <TouchableOpacity
              style={[styles.testButton, styles.buttonGreen]}
              onPress={handleFillSuccess}
              activeOpacity={0.8}
            >
              <Text style={styles.buttonTextGreen}>Fill 4719 (Success)</Text>
            </TouchableOpacity>

            <TouchableOpacity
              style={[styles.testButton, styles.buttonRed]}
              onPress={handleFillFail}
              activeOpacity={0.8}
            >
              <Text style={styles.buttonTextRed}>Fill 1234 (Fail)</Text>
            </TouchableOpacity>
          </View>

          <View style={styles.buttonsRow}>
            <TouchableOpacity
              style={styles.testButton}
              onPress={handleReplay}
              activeOpacity={0.8}
            >
              <Text style={styles.buttonText}>Replay</Text>
            </TouchableOpacity>

            <TouchableOpacity
              style={styles.testButton}
              onPress={handleReset}
              activeOpacity={0.8}
            >
              <Text style={styles.buttonText}>Reset</Text>
            </TouchableOpacity>
          </View>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
};

